import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        try (
            BufferedReader br = new BufferedReader(new FileReader("origen.txt"));
            BufferedWriter bw = new BufferedWriter(new FileWriter("destino.txt"))
        ) {
            String linea;
            int numLinea = 0;
            while ((linea = br.readLine()) != null) {
                bw.write(linea);
                bw.newLine();
                numLinea++;
                System.out.println("Línea " + numLinea + " copiada: " + linea);
            }
            System.out.println("Archivo copiado: " + numLinea + " líneas");
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}
